changeSet.sql:
alter table untersuchungimpfstatuskrankheit add column impfschutzgegebenmigration varchar(30);
alter table untersuchungimpfstatuskrankheit_aud add column impfschutzgegebenmigration varchar(30);
update untersuchungimpfstatuskrankheit set impfschutzgegebenmigration = 'JA' where impfschutzgegeben is true;
update untersuchungimpfstatuskrankheit set impfschutzgegebenmigration = 'NEIN' where impfschutzgegeben is false;
update untersuchungimpfstatuskrankheit set impfschutzgegebenmigration = 'KEINE_ANGABE' where impfschutzgegeben is null;
update untersuchungimpfstatuskrankheit_aud set impfschutzgegebenmigration = 'JA' where impfschutzgegeben is true;
update untersuchungimpfstatuskrankheit_aud set impfschutzgegebenmigration = 'NEIN' where impfschutzgegeben is false;
update untersuchungimpfstatuskrankheit_aud set impfschutzgegebenmigration = 'KEINE_ANGABE' where impfschutzgegeben is null;
alter table untersuchungimpfstatuskrankheit drop column if exists impfschutzgegeben;
alter table untersuchungimpfstatuskrankheit_aud drop column if exists impfschutzgegeben;
alter table untersuchungimpfstatuskrankheit rename column impfschutzgegebenmigration to impfschutzgegeben;
alter table untersuchungimpfstatuskrankheit_aud rename column impfschutzgegebenmigration to impfschutzgegeben;

alter table if exists untersuchunghoerenaudiogramm alter column audiogrammbeurteilung set data type varchar(2000);
alter table if exists untersuchunghoerenaudiogramm alter column empfehlung set data type varchar(2000);
alter table if exists untersuchunghoerenaudiogramm alter column zusaetzlicheangaben set data type varchar(2000);
alter table if exists untersuchunghoerenotoskopie alter column otoskopielinks set data type varchar(2000);
alter table if exists untersuchunghoerenotoskopie alter column otoskopierechts set data type varchar(2000);
alter table if exists untersuchungsehenbeurteilung alter column empfehlung set data type varchar(2000);
alter table if exists untersuchungsehenbeurteilung alter column fernvisus set data type varchar(2000);
alter table if exists untersuchungsehenbeurteilung alter column nahvisus set data type varchar(2000);
alter table if exists untersuchungsehenbeurteilung alter column strabismus set data type varchar(2000);
